/**
 * Localization — 1:1 port of `Services/LocalizationService.cs`, extended
 * with five more languages (zh/hi/ja/id/fil) and a broader key set covering
 * every panel's header title (`panel.*`) and the Settings page's own
 * section labels (`settings.section.*`), on top of the original `nav.*` /
 * `settings.language` keys.
 *
 * The original resolves strings client-side from a static table keyed by
 * `Settings.Language`, so this stays in the frontend rather than becoming a
 * Tauri command: it is a pure lookup with no I/O.
 *
 * Lookup order matches the C# `T(string key)` exactly: the active language,
 * then English, then the key itself as a last resort (so a missing string is
 * visible rather than blank). Coverage note: this covers the launcher's
 * persistent chrome (nav buttons), every panel's header title, and the
 * Settings page's section labels — the highest-traffic surfaces regardless
 * of which feature a user is in. Deeper per-view body copy (the long tail of
 * tooltips/empty-states/toasts inside each individual feature view) isn't
 * wired to `t()` yet; those fall back to their existing English text, which
 * is a clean, working fallback rather than a broken one. Extending coverage
 * is additive: add the key here (all languages, or just `en` — missing
 * per-language keys fall back to English), then replace the literal string
 * at the call site with `t('your.key', lang)` (or, for a component that
 * doesn't have `lang`/`settings` threaded in, `./i18nStore.svelte`'s
 * zero-arg `t('your.key')`).
 */

export interface LanguageOption {
  code: string
  label: string
}

/** Port of `LocalizationService.Languages`, extended with five more. */
export const LANGUAGES: LanguageOption[] = [
  { code: 'en', label: 'English' },
  { code: 'es', label: 'Español' },
  { code: 'de', label: 'Deutsch' },
  { code: 'fr', label: 'Français' },
  { code: 'pt', label: 'Português' },
  { code: 'zh', label: '简体中文' },
  { code: 'hi', label: 'हिन्दी' },
  { code: 'ja', label: '日本語' },
  { code: 'id', label: 'Bahasa Indonesia' },
  { code: 'fil', label: 'Filipino' },
]

type Table = Record<string, Record<string, string>>

