/**
 * Port of `LocalizationService.T`. `lang` is `Settings.Language`.
 *
 * `params` fills `{name}`-style placeholders in the translated string, e.g.
 * `t('toast.created', lang, { name: pack.name })` against `'Created "{name}".'`.
 */
export function t(
  key: string,
  lang: string | undefined,
  params?: Record<string, string | number>,
): string {
  const active = lang ? TABLE[lang] : undefined
  let value = active && key in active ? active[key] : TABLE.en[key] ?? key
  if (params) {
    for (const [name, val] of Object.entries(params)) {
      value = value.split(`{${name}}`).join(String(val))
    }
  }
  return value
}
